-- =============================================================================
-- SKEMA POSTGRESQL (SUPABASE) — hasil migrasi dari drone_schema.sql (MySQL)
-- =============================================================================
-- Jalankan SEKALI di Supabase: buka project -> SQL Editor -> tempel file ini
-- -> Run. Aman diulang: semua objek di-DROP dulu sebelum dibuat.
--
-- PERBEDAAN UTAMA vs versi MySQL (dan alasannya):
--   AUTO_INCREMENT      -> GENERATED BY DEFAULT AS IDENTITY (standar SQL)
--   ENUM('a','b')       -> tipe ENUM asli PostgreSQL (CREATE TYPE)
--   TIMESTAMP           -> TIMESTAMPTZ. PostgreSQL menyimpan zona waktu, jadi
--                          data dari node ROS (UTC) tidak bergeser saat dibaca
--                          browser di WIB — bug halus yang tidak ada di sini.
--   FLOAT / DOUBLE      -> REAL / DOUBLE PRECISION
--   JSON                -> JSONB (terindeks & lebih cepat di PostgreSQL)
--   INDEX inline        -> CREATE INDEX terpisah (PostgreSQL tidak punya
--                          sintaks INDEX di dalam CREATE TABLE)
--   INSERT IGNORE       -> INSERT ... ON CONFLICT DO NOTHING
--   utf8mb4             -> tidak perlu, PostgreSQL sudah UTF-8 penuh
-- =============================================================================

-- --- Bersihkan objek lama ------------------------------------------------
-- CASCADE otomatis mengurus foreign key, jadi tidak perlu padanan
-- SET FOREIGN_KEY_CHECKS=0 seperti di MySQL.
DROP TABLE IF EXISTS harvest_classifications CASCADE;
DROP TABLE IF EXISTS image_metadata CASCADE;
DROP TABLE IF EXISTS harvest_jobs CASCADE;
DROP TABLE IF EXISTS field_boundaries CASCADE;
DROP TABLE IF EXISTS error_logs CASCADE;
DROP TABLE IF EXISTS obstacle_logs CASCADE;
DROP TABLE IF EXISTS wind_logs CASCADE;
DROP TABLE IF EXISTS battery_logs CASCADE;
DROP TABLE IF EXISTS telemetry_logs CASCADE;
DROP TABLE IF EXISTS missions CASCADE;
DROP TABLE IF EXISTS drones CASCADE;
DROP TABLE IF EXISTS users CASCADE;

DROP TYPE IF EXISTS user_role CASCADE;
DROP TYPE IF EXISTS drone_status CASCADE;
DROP TYPE IF EXISTS mission_status CASCADE;
DROP TYPE IF EXISTS error_severity CASCADE;
DROP TYPE IF EXISTS job_status CASCADE;

-- --- Tipe ENUM ------------------------------------------------------------
CREATE TYPE user_role      AS ENUM ('admin', 'operator', 'viewer');
CREATE TYPE drone_status   AS ENUM ('active', 'maintenance', 'retired');
CREATE TYPE mission_status AS ENUM ('planned', 'in_progress', 'completed', 'failed', 'aborted');
CREATE TYPE error_severity AS ENUM ('info', 'warning', 'error', 'critical');
CREATE TYPE job_status     AS ENUM ('pending', 'processing', 'completed', 'failed');


-- =======================================================
-- 1. TABEL MASTER: USERS & DRONES
-- =======================================================
CREATE TABLE users (
    id            INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username      VARCHAR(50) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    role          user_role DEFAULT 'operator',
    created_at    TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE drones (
    id         INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name       VARCHAR(100) NOT NULL,
    model      VARCHAR(100),
    status     drone_status DEFAULT 'active',
    created_at TIMESTAMPTZ DEFAULT now()
);

-- Data dummy dasar
INSERT INTO users (id, username, password_hash, role)
VALUES (1, 'iqball', 'hashed_password_here', 'admin')
ON CONFLICT (id) DO NOTHING;

INSERT INTO drones (id, name, model, status)
VALUES (1, 'PX4-Gazebo-X500', 'Quadcopter', 'active')
ON CONFLICT (id) DO NOTHING;

-- Kolom IDENTITY tidak tahu bahwa kita menyisipkan id manual di atas.
-- Tanpa penyelarasan ini, INSERT berikutnya (tanpa id) memakai 1 dan
-- langsung bentrok primary key.
SELECT setval(pg_get_serial_sequence('users', 'id'),  GREATEST((SELECT MAX(id) FROM users), 1));
SELECT setval(pg_get_serial_sequence('drones', 'id'), GREATEST((SELECT MAX(id) FROM drones), 1));


-- =======================================================
-- 2. TABEL TRANSAKSI: MISSIONS
-- =======================================================
CREATE TABLE missions (
    id                   INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    drone_id             INT NOT NULL REFERENCES drones(id) ON DELETE CASCADE,
    operator_id          INT REFERENCES users(id) ON DELETE SET NULL,
    start_time           TIMESTAMPTZ DEFAULT now(),
    end_time             TIMESTAMPTZ,
    start_x              REAL,
    start_y              REAL,
    dest_x               REAL,
    dest_y               REAL,
    flight_mode          VARCHAR(50) DEFAULT 'auto',
    -- Jarak drone -> waypoint tujuan pada SAAT "Send Goal" ditekan (meter).
    -- Sengaja dipisah dari total_distance_m: yang ini jarak rencana lurus ke
    -- target, sedangkan total_distance_m adalah jarak tempuh aktual (yang
    -- selalu lebih besar karena drone menghindari rintangan).
    goal_distance_m      REAL,
    -- Basis perhitungan goal_distance_m: 'gps' (haversine lat/lon) atau
    -- 'local' (Euclidean pada koordinat lokal). Keduanya satuan METER.
    goal_distance_source VARCHAR(10),
    total_distance_m     REAL DEFAULT 0.0,
    battery_used_percent REAL DEFAULT 0.0,
    status               mission_status DEFAULT 'in_progress',
    arrival_time         TIMESTAMPTZ,
    rth_start_time       TIMESTAMPTZ,
    landing_time         TIMESTAMPTZ,
    total_duration_sec   INT DEFAULT 0
);


-- =======================================================
-- 3. TABEL LOGGING: TELEMETRY, BATTERY, OBSTACLES, ERROR
-- =======================================================
CREATE TABLE telemetry_logs (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    mission_id  INT REFERENCES missions(id) ON DELETE CASCADE,
    drone_id    INT NOT NULL REFERENCES drones(id) ON DELETE CASCADE,
    recorded_at TIMESTAMPTZ(3) DEFAULT now(),
    x           REAL,
    y           REAL,
    z           REAL,
    latitude    DOUBLE PRECISION,
    longitude   DOUBLE PRECISION,
    altitude_m  REAL,
    velocity_x  REAL,
    velocity_y  REAL,
    velocity_z  REAL,
    speed_mps   REAL,
    yaw_rad     REAL,
    pitch_rad   REAL,
    roll_rad    REAL,
    heading_deg REAL,
    flight_mode VARCHAR(50),
    nav_state   VARCHAR(50),
    source      VARCHAR(50),
    raw_payload JSONB
);

CREATE INDEX idx_telemetry_mission_time ON telemetry_logs (mission_id, recorded_at);

CREATE TABLE battery_logs (
    id                      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    mission_id              INT REFERENCES missions(id) ON DELETE CASCADE,
    drone_id                INT NOT NULL REFERENCES drones(id) ON DELETE CASCADE,
    recorded_at             TIMESTAMPTZ(3) DEFAULT now(),
    battery_percent         REAL,
    voltage_v               REAL,
    current_a               REAL,
    estimated_remaining_sec REAL,
    warning_level           VARCHAR(20),
    raw_payload             JSONB
);

CREATE TABLE wind_logs (
    id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    mission_id         INT REFERENCES missions(id) ON DELETE CASCADE,
    drone_id           INT NOT NULL REFERENCES drones(id) ON DELETE CASCADE,
    recorded_at        TIMESTAMPTZ(3) DEFAULT now(),
    wind_speed_mps     REAL,
    wind_direction_deg REAL,
    wind_north_mps     REAL,
    wind_east_mps      REAL,
    safety_status      VARCHAR(20),
    raw_payload        JSONB
);

CREATE TABLE obstacle_logs (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    obstacle_uid     VARCHAR(100),
    mission_id       INT REFERENCES missions(id) ON DELETE CASCADE,
    drone_id         INT NOT NULL REFERENCES drones(id) ON DELETE CASCADE,
    detected_at      TIMESTAMPTZ(3) DEFAULT now(),
    x                REAL,
    y                REAL,
    z                REAL,
    latitude         DOUBLE PRECISION,
    longitude        DOUBLE PRECISION,
    radius_m         REAL,
    width_m          REAL,
    height_m         REAL,
    obstacle_type    VARCHAR(50),
    source           VARCHAR(50),
    confidence       REAL,
    avoidance_action VARCHAR(50),
    raw_payload      JSONB
);

CREATE TABLE error_logs (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    mission_id  INT REFERENCES missions(id) ON DELETE CASCADE,
    drone_id    INT NOT NULL REFERENCES drones(id) ON DELETE CASCADE,
    occurred_at TIMESTAMPTZ(3) DEFAULT now(),
    severity    error_severity DEFAULT 'info',
    subsystem   VARCHAR(50),
    event_type  VARCHAR(100),
    error_code  VARCHAR(50),
    message     TEXT,
    context     JSONB,
    resolved_at TIMESTAMPTZ
);


-- =======================================================
-- 4. TABEL RICE HARVEST CLASSIFICATION & GEOSPATIAL AI
-- =======================================================
CREATE TABLE field_boundaries (
    id               INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    field_name       VARCHAR(100) NOT NULL,
    boundary_geojson JSONB,
    target_crop      VARCHAR(50) DEFAULT 'padi',
    area_ha          REAL DEFAULT 0.0,
    created_at       TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE harvest_jobs (
    id                    VARCHAR(100) PRIMARY KEY,
    mission_id            INT REFERENCES missions(id) ON DELETE SET NULL,
    job_name              VARCHAR(255),
    status                job_status DEFAULT 'pending',
    progress_percent      REAL DEFAULT 0.0,
    original_filename     VARCHAR(255),
    input_file_path       TEXT,
    output_file_path      TEXT,
    output_geotiff_path   TEXT,
    total_area_m2         REAL DEFAULT 0.0,
    estimated_yield_tons  REAL DEFAULT 0.0,
    error_message         TEXT,
    created_at            TIMESTAMPTZ DEFAULT now(),
    completed_at          TIMESTAMPTZ
);

CREATE TABLE harvest_classifications (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    job_id      VARCHAR(100) NOT NULL REFERENCES harvest_jobs(id) ON DELETE CASCADE,
    class_name  VARCHAR(100) NOT NULL,
    pixel_count BIGINT DEFAULT 0,
    area_m2     REAL DEFAULT 0.0,
    percentage  REAL DEFAULT 0.0,
    color_hex   VARCHAR(20)
);

CREATE TABLE image_metadata (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    job_id          VARCHAR(100) NOT NULL REFERENCES harvest_jobs(id) ON DELETE CASCADE,
    camera_model    VARCHAR(100),
    focal_length_mm REAL,
    iso             INT,
    exposure_time   VARCHAR(50),
    gps_latitude    DOUBLE PRECISION,
    gps_longitude   DOUBLE PRECISION,
    gps_altitude_m  REAL,
    capture_time    TIMESTAMPTZ,
    raw_exif        JSONB
);


-- =======================================================
-- 5. KEAMANAN: ROW LEVEL SECURITY
-- =======================================================
-- Supabase mengekspos SETIAP tabel lewat API PostgREST publik yang memakai
-- kunci `anon`. Tanpa RLS, siapa pun yang tahu URL project + anon key bisa
-- membaca seluruh log penerbangan.
--
-- Aplikasi kita TIDAK memakai jalur itu: node ROS dan API route Next.js
-- terhubung langsung sebagai role `postgres`, yang otomatis MELEWATI RLS.
-- Jadi mengaktifkan RLS tanpa policy apa pun = pintu API publik tertutup
-- rapat, sementara aplikasi tetap berjalan normal.
ALTER TABLE users                   ENABLE ROW LEVEL SECURITY;
ALTER TABLE drones                  ENABLE ROW LEVEL SECURITY;
ALTER TABLE missions                ENABLE ROW LEVEL SECURITY;
ALTER TABLE telemetry_logs          ENABLE ROW LEVEL SECURITY;
ALTER TABLE battery_logs            ENABLE ROW LEVEL SECURITY;
ALTER TABLE wind_logs               ENABLE ROW LEVEL SECURITY;
ALTER TABLE obstacle_logs           ENABLE ROW LEVEL SECURITY;
ALTER TABLE error_logs              ENABLE ROW LEVEL SECURITY;
ALTER TABLE field_boundaries        ENABLE ROW LEVEL SECURITY;
ALTER TABLE harvest_jobs            ENABLE ROW LEVEL SECURITY;
ALTER TABLE harvest_classifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE image_metadata          ENABLE ROW LEVEL SECURITY;
